mapper.select:
SELECT COUNT(*)
FROM ugc_report
WHERE post_id = #{postId}

SELECT r.id, r.post_id, r.reporter_id, u.display_name AS reporter_name,
       r.reason, r.status, r.reviewer_id, r.created_at, r.resolved_at
FROM ugc_report r
JOIN users u ON u.id = r.reporter_id
WHERE r.post_id = #{postId}
  AND r.id = #{reportId}
